data.minimal_example:
import 'package:platform/platform.dart';

void main() {
  switch (Platform.current) {
    case Platform(:var nativePlatform?):
      print('Running on ${nativePlatform.operatingSystem} v.${nativePlatform.operatingSystemVersion}');
    case Platform(:var browserPlatform?):
      print('Running on ${browserPlatform.userAgent}');
  }
}
